const variantsByProducts = `-- name: VariantsByProducts :many
SELECT v.id, v.product_id, v.sku, v.barcode, v.name, v.attributes, v.price_extra, v.status,
       v.weight, v.weight_unit, v.length, v.width, v.height, v.dimension_unit,
       i.on_hand, i.reserved, i.available
  FROM product_variant v
  LEFT JOIN inventory i ON i.site_id = v.site_id AND i.variant_id = v.id
 WHERE v.product_id = ANY($1::uuid[])
 ORDER BY v.sort_order, v.id
`

type VariantsByProductsRow struct {
	ID            uuid.UUID
	ProductID     uuid.UUID
	Sku           *string
	Barcode       *string
	Name          *string
	Attributes    json.RawMessage
	PriceExtra    decimal.Decimal
	Status        string
	Weight        *decimal.Decimal
	WeightUnit    *string
	Length        *decimal.Decimal
	Width         *decimal.Decimal
	Height        *decimal.Decimal
	DimensionUnit *string
	OnHand        *int64
	Reserved      *int64
	Available     *int64
}

func (q *Queries) VariantsByProducts(ctx context.Context, ids []uuid.UUID) ([]VariantsByProductsRow, error) {
	rows, err := q.db.Query(ctx, variantsByProducts, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VariantsByProductsRow
	for rows.Next() {
		var i VariantsByProductsRow
		if err := rows.Scan(
			&i.ID,
			&i.ProductID,
			&i.Sku,
			&i.Barcode,
			&i.Name,
			&i.Attributes,
			&i.PriceExtra,
			&i.Status,
			&i.Weight,
			&i.WeightUnit,
			&i.Length,
			&i.Width,
			&i.Height,
			&i.DimensionUnit,
			&i.OnHand,
			&i.Reserved,
			&i.Available,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const variantsOfProduct = `-- name: VariantsOfProduct :many
SELECT id, attributes FROM product_variant WHERE product_id = $1
`

type VariantsOfProductRow struct {
	ID         uuid.UUID
	Attributes json.RawMessage
}

func (q *Queries) VariantsOfProduct(ctx context.Context, productID uuid.UUID) ([]VariantsOfProductRow, error) {
	rows, err := q.db.Query(ctx, variantsOfProduct, productID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VariantsOfProductRow
	for rows.Next() {
		var i VariantsOfProductRow
		if err := rows.Scan(&i.ID, &i.Attributes); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
